#pragma once
#include <cstdint>
namespace study_session {
inline constexpr std::uint64_t default_seed = 0xC0FFEE123456789ull;
inline constexpr std::uint64_t garbage_tag = 0x9E3779B97F4A7C15ull;
inline constexpr std::uint64_t normalize(std::uint64_t seed) noexcept {
    return seed ? seed : default_seed;
}
// The result may be zero; the receiving engine applies its own zero policy.
inline constexpr std::uint64_t garbage_seed(std::uint64_t seed) noexcept {
    return normalize(seed) ^ garbage_tag;
}
} // namespace study_session

static HoleSource seeded(std::uint64_t requested_seed) noexcept {
    HoleSource source;
    source.rng_.emplace(study_session::garbage_seed(requested_seed));
    source.cursor_ = 0u;
    return source;
}

unsigned next() noexcept {
    if (rng_.has_value()) {
        return static_cast<unsigned>(rng_->nextUInt(10u));
    }
    const unsigned value = holes_[cursor_];
    cursor_ = (cursor_ + 1u) % 3u;
    return value;
}

if (candidate.pending_garbage_ > 0) {
    const int hole = static_cast<int>(candidate.holes_.next());
    const auto inserted = study_combat::insert(
        candidate.board_, candidate.pending_garbage_, hole);
    if (!inserted) return Step::invalid;
    candidate.board_ = inserted->board;
    candidate.last_garbage_ = inserted->rows;
    candidate.pending_garbage_ = 0;
    overflow = inserted->overflow;
}

static std::optional<Round> create_seeded(const study_grid::Grid& board,
                                         std::uint64_t seed,
                                         int interval = 30) noexcept {
    return create(board, study_next::SeededBagSource(seed),
                  study_holes::HoleSource::seeded(seed), interval);
}

